steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(first: 20, filter: { title: { contains: \"Renew SSO certificate\" } }) { nodes { id title priority priorityName assignee { name email } createdBy { email } team { name } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(first: 20, filter: { title: { contains: \"Renew SSO certificate\" } }) { nodes { id title priority assignee { name email } creator { email } team { name } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(id: \"i-it-sso-b\", input: { priority: 1 }) { success issue { id title priority } } }"
  }'
